require_once __DIR__.'/document_studio_common.php';$u=uid();try{if($_SERVER['REQUEST_METHOD']!=='POST')out(['success'=>false,'error'=>'Methode nicht erlaubt.'],405);$id=trim((string)($_POST['document_id']??''));$d=doc($pdo,$id);if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)out(['success'=>false,'error'=>'Upload fehlgeschlagen.'],422);$f=$_FILES['file'];if($f['size']>20*1024*1024)out(['success'=>false,'error'=>'Maximal 20 MB.'],413);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'])?:'application/octet-stream';$allow=['image/png','image/jpeg','image/webp','image/gif','application/pdf','text/plain','text/csv','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];if(!in_array($mime,$allow,true))out(['success'=>false,'error'=>'Dateityp nicht erlaubt: '.$mime],415);$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$stored=uuid4().($ext?'.'.$ext:'');$dir=__DIR__.'/../uploads/documents/'.$d['project_id'].'/'.$id;if(!is_dir($dir)&&!mkdir($dir,0775,true))throw new RuntimeException('Uploadordner konnte nicht erstellt werden.');$target=$dir.'/'.$stored;if(!move_uploaded_file($f['tmp_name'],$target))throw new RuntimeException('Datei konnte nicht gespeichert werden.');$fid=uuid4();$rel='uploads/documents/'.$d['project_id'].'/'.$id.'/'.$stored;$pdo->prepare('INSERT INTO requirement_document_files(id,project_id,document_id,original_name,stored_name,relative_path,mime_type,file_size,sha256,created_by)VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$fid,$d['project_id'],$id,$f['name'],$stored,$rel,$mime,$f['size'],hash_file('sha256',$target),$u]);out(['success'=>true,'file'=>['id'=>$fid,'name'=>$f['name'],'size'=>$f['size'],'mime'=>$mime]]);}catch(Throwable$e){out(['success'=>false,'error'=>$e->getMessage()],500);}
